#!/bin/sh
# LS-UX-1 F: prove the console API sees the real client address through the
# real chain: client -> [single-IP edge] -> app-proxy console router -> pinned
# Caddy (generated by tunnex.yml) -> nginx image config -> API router (chi
# RealIP). Forged headers from clients and from non-proxy sources are ignored.
# Needs Docker and Go. Creates only lsux1-cip-* resources and removes them.
set -eu
ROOT=$(CDPATH= cd -- "$(dirname "$0")/../.." && pwd)
ARCH=$(docker info --format '{{.Architecture}}' | sed 's/aarch64/arm64/;s/x86_64/amd64/')
W=$(mktemp -d "${TUNNEX_WALK_TMPDIR:-$HOME}/.lsux1-cip.XXXXXX")
CADDY=$(sed -n 's/^    image: \${TUNNEX_CADDY_IMAGE:-\(caddy@sha256:[0-9a-f]*\)}$/\1/p' "$ROOT/deploy/tunnex.yml")
NGINX=$(sed -n 's/^FROM \(nginxinc[^ ]*\).*/\1/p' "$ROOT/deploy/docker/nginx.Dockerfile" | head -1)
cleanup() {
  docker rm -f lsux1-cip-api lsux1-cip-nginx lsux1-cip-caddy lsux1-cip-appproxy lsux1-cip-edge >/dev/null 2>&1 || true
  docker network rm lsux1-cip-def lsux1-cip-edgenet >/dev/null 2>&1 || true
  rm -rf "$W"
}
[ -n "${KEEP:-}" ] || trap cleanup EXIT
fail() { echo "console client address walk: $*" >&2; exit 1; }
build() { (cd "$1" && GOOS=linux GOARCH=$ARCH CGO_ENABLED=0 go build -o "$W/$2" "$3"); }
build "$ROOT/apps/api" echo ./internal/http/testdata/clientipecho
build "$ROOT/apps/app-proxy" appproxy ./internal/proxy/testdata/consoleprobe
build "$ROOT/packages/apptransport" edge ./sniedge/testdata/edgeprobe
build "$ROOT/packages/apptransport" client ./proxyproto/testdata/httpsclient
openssl req -x509 -newkey rsa:2048 -nodes -keyout "$W/key.pem" -out "$W/cert.pem" -days 1 -subj /CN=console.test -addext subjectAltName=DNS:console.test >/dev/null 2>&1
printf '%s\n' "$(openssl rand -hex 32)" >"$W/edge.token"; chmod 0600 "$W/edge.token"
# The Caddy script exactly as tunnex.yml renders it; only local test certificates are added.
awk '/^  caddy:/{c=1} c&&/^      - \|$/{s=1;next} s&&/^    ports:/{exit} s{sub(/^        /,"");print}' "$ROOT/deploy/tunnex.yml" |
  sed 's/\$\$/$/g' | sed "s#printf '%s\\\\n' '{' \"\$edge_servers\" '}'#printf '%s\\\\n' '{' '  local_certs' \"\$edge_servers\" '}'#" >"$W/caddy.sh"
grep -q "local_certs" "$W/caddy.sh" || fail 'could not prepare the Caddy script'
docker network create lsux1-cip-def >/dev/null
docker network create --internal --subnet 172.31.254.0/29 lsux1-cip-edgenet >/dev/null
docker run -d --name lsux1-cip-api --network lsux1-cip-def --network-alias api -v "$W/echo:/echo:ro" alpine /echo >/dev/null
docker run -d --name lsux1-cip-nginx --network lsux1-cip-def --network-alias nginx -v "$ROOT/deploy/nginx/nginx.conf:/etc/nginx/conf.d/default.conf:ro" "$NGINX" >/dev/null
docker create --name lsux1-cip-caddy --network lsux1-cip-def --network-alias caddy -e TUNNEX_EDGE_LISTEN=https://console.test \
  -e TUNNEX_HTTP_CONSOLE_ENABLED=false -e TUNNEX_EDGE_APP_PROXY_FROM=172.31.254.4/32 \
  -v "$W/caddy.sh:/s.sh:ro" --entrypoint sh "$CADDY" /s.sh >/dev/null
docker network connect --ip 172.31.254.3 lsux1-cip-edgenet lsux1-cip-caddy
docker start lsux1-cip-caddy >/dev/null
i=0; until docker cp lsux1-cip-caddy:/data/caddy/pki/authorities/local/root.crt "$W/caddy-root.crt" 2>/dev/null; do i=$((i+1)); [ "$i" -lt 40 ] || fail 'Caddy did not start'; sleep 0.5; done
start_appproxy() {
  docker rm -f lsux1-cip-appproxy >/dev/null 2>&1 || true
  # Like the App Access overlay: on the default network too, so the name
  # `caddy` resolves there; only the pinned dial leaves on the edge network.
  docker create --name lsux1-cip-appproxy --network lsux1-cip-def -e CONSOLE=https://console.test \
    -e UPSTREAM=https://caddy:443 -e PIN=172.31.254.3:443 -e UPSTREAM_CA=/w/caddy-root.crt -e CERT=/w/cert.pem -e KEY=/w/key.pem "$@" \
    -v "$W:/w:ro" -v "$W/appproxy:/appproxy:ro" alpine /appproxy >/dev/null
  docker network connect --ip 172.31.254.4 lsux1-cip-edgenet lsux1-cip-appproxy
  docker start lsux1-cip-appproxy >/dev/null
  sleep 1
}
ask() { docker run --rm --network lsux1-cip-edgenet --ip "$1" -v "$W/client:/client:ro" alpine /client "$2" console.test | sed -n 's/^api-sees=\([0-9.]*\).*/\1/p'; }
start_appproxy
got=""; i=0; while [ -z "$got" ] && [ "$i" -lt 20 ]; do got=$(ask 172.31.254.5 172.31.254.4:443 || true); i=$((i+1)); sleep 0.5; done
[ "$got" = 172.31.254.5 ] || fail "client -> app-proxy -> Caddy: API saw '$got', want 172.31.254.5"
got=$(ask 172.31.254.6 172.31.254.3:443)
[ "$got" = 172.31.254.6 ] || fail "forged headers sent straight to Caddy were trusted: API saw '$got'"
# Behind the single-IP edge: client -> edge -> app-proxy (token) -> Caddy.
start_appproxy -e EDGE_TOKEN_FILE=/w/edge.token
docker run -d --name lsux1-cip-edge --network lsux1-cip-edgenet --ip 172.31.254.2 -e DEFAULT=172.31.254.4:443 -e DEFAULT_TOKEN=true \
  -e EDGE_TOKEN_FILE=/w/edge.token -v "$W:/w:ro" alpine /w/edge >/dev/null
sleep 1
got=$(ask 172.31.254.5 172.31.254.2:443)
[ "$got" = 172.31.254.5 ] || fail "client -> edge -> app-proxy -> Caddy: API saw '$got', want 172.31.254.5"
echo 'console client address walk passed: real client address end to end; forged headers ignored'
